import { createContext, useEffect, useState } from 'react';
import ProfileForm from '../components/ProfileForm/ProfileForm';
import { auth } from '../firebase/auth';

const AuthContext = createContext({ user: null });

export const AuthContextProvider = ({ children }) => {

    const [user, setUser] = useState("loading");

    const isInvalid = user && user !== 'loading' && !user.displayName;
    let timer;

    useEffect(() => {
        const authUnSubscription = auth.onAuthStateChanged(currentUser => {
            if (currentUser) {
                if (!currentUser.displayName) {
                    const date = new Date();
                    let futureTime = localStorage.getItem('expiry-time');
                    if (!futureTime) {
                        futureTime = new Date((date.getTime() + 15) * 60000).getTime();
                        localStorage.setItem('expiry-time', futureTime);
                    }
                    timer = setTimeout(() => {
                        localStorage.clear();
                        auth.signOut();
                    }, futureTime - new Date().getTime());
                    clearTimeout(timer)
                }
            }
            setUser(currentUser);
        })
        return () => {
            authUnSubscription();
            clearTimeout(timer);
        };
    }, [])

    const onUserStateChange = () => {
        setUser("loading");
        setTimeout(() => {
            setUser(auth.currentUser);
        }, 1000)
    }
    return (
        <AuthContext.Provider value={{ user }}>
            {isInvalid ? <ProfileForm onSuccess={onUserStateChange} /> : children}
        </AuthContext.Provider>
    )
}


export default AuthContext;