import { onLogin } from '../../firebase/auth';
import Form from '../../hoc/Form';
import TextField from '../../ui/TextField/TextField';

const PhoneForm = ({ onSubmit, phoneNumber }) => {
    const onPhoneSubmit = props => {
        const phoneNumber = props.values.phoneNumber;
        onLogin(phoneNumber)
            .then(confirmation => {
                onSubmit({ confirmation, phoneNumber, status: true });
                props.onSuccess();
            })
            .catch(props.onFailure);
    }
    return (
        <Form
            onSubmit={onPhoneSubmit}
            isRecaptcha={true}
            id='sign-in-button'
            className='flex-1 mt-lg-5 d-flex flex-column gap-inherit'
            footer={(isLoading, id) => (
                <button
                    id={id}
                    className='btn-primary mt-md-0 me-md-auto mt-auto'
                    loading={isLoading ? "loading" : ""}
                    disabled={isLoading}

                >Send OTP</button>
            )}>
            <TextField
                defaultValue={phoneNumber}
                label='Phone Number'
                name='phoneNumber'
                className='mx-auto w-100'
            />
        </Form>
    )
}

export default PhoneForm;