import React, { useEffect, useRef, useState } from "react";
import { getRecaptcha } from "../firebase/auth";

const Form = ({ footer, onSubmit, children, isRecaptcha = false, id, ...props }) => {
    const [{ err, isLoading, message }, setStatus] = useState({});

    const formRef = useRef();

    const onFormSubmit = e => {
        if (isLoading) return;
        if (typeof e === "object") e.preventDefault();

        const form = formRef.current;

        if (!form.classList.contains('submitted')) form.classList.add('submittted')

        const formData = new FormData(form);
        const values = {};
        for (let key of formData.keys()) {
            const { type, value, files } = form[key];
            values[key] = type === 'file' ? files : (type === 'number' ? +value : (value || formData.getAll(key)));
        }

        const isValid = form.checkValidity();
        form.classList.add('submitted');
        if (!isValid) return;
        setStatus({ isLoading: true });


        if (!onSubmit) return;
        onSubmit({
            values,
            form,
            onSuccess: message => {
                form.classList.remove('submitted');
                form.reset();
                setStatus({ message });
            },
            onFailure: (err) => {
                console.log(err)
                setStatus({ err })
            },
            formData,
        })
    }

    useEffect(() => {
        if (isRecaptcha && id) getRecaptcha(id, onFormSubmit, err => setStatus({ err }))
    }, [])


    return (
        <form onSubmit={onFormSubmit} {...props} noValidate="novalidate" ref={formRef}>
            {children}
            {err && <small className='tx-danger'>{err.message}</small>}
            {message && <small className="tx-primary">{message}</small>}
            {footer && footer(isLoading, id)}
        </form>
    )
}

export default Form;